        {"항목":"로마 식민지 빌립보에서의 평강", "내용":"로마의 팍스 로마나(로마의 평화)가 지배하던 빌립보에서 바울은 진정한 평강의 근원이 로마가 아닌 예수 그리스도임을 선언한다", "목회적활용":"세상이 주는 평화와 그리스도가 주시는 평강의 차이를 가르칠 수 있다"}
