        {"대지":"결론", "내용":"나는 검증된 사람인가? 다양한 상황에서 신실하게 사역하며 공동체가 인정하는 삶을 살고 있는가? 검증은 순간이 아닌 시간이다. 오늘 신실하게 사는 것이 미래의 검증이 된다", "예화_적용":"매일 신실하게—큰 결단 하나보다 매일의 작은 신실함이 검증을 만든다"}
